\begin{array}{l} H ^ {\prime (i)} = \operatorname {M u l t i H e a d} (\operatorname {n o r m} \left(\mathrm {H} ^ {\left(\mathrm {i} - 1\right)}\right)) + \mathrm {H} ^ {\left(\mathrm {i} - 1\right)} \tag {6} \\ H ^ {(i)} = \mathrm {F F N} (\mathrm {n o r m} \left(\mathrm {H} ^ {\prime ^ {(i)}}\right)) + \mathrm {H} ^ {\prime^ {(i)}} \\ \end{array}

